/** @type {Map<string, ReadonlyArray<TaleNode>>} Parsed trees, filled on first use. */
const PARSED = new Map();

/**
 * @typedef {readonly [string, Readonly<Record<string, string>>, number, ReadonlyArray<TaleNode>?]} TaleNode
 *   One stored SVG node: tag, attributes, switch-mix mask (-1 = always) and,
 *   for a group, its children.
 */

/**
 * Parse and deep-freeze one stored tree, once.
 *
 * @param {Readonly<Record<string, string>>} table
 * @param {string} prefix
 * @param {string} key
 * @returns {ReadonlyArray<TaleNode> | null}
 */
function parsedTree(table, prefix, key) {
  if (!Object.hasOwn(table, key)) {
    return null;
  }
  const cacheKey = `${prefix}:${key}`;
  const known = PARSED.get(cacheKey);
  if (known !== undefined) {
    return known;
  }
  /** @type {ReadonlyArray<TaleNode>} */
  const tree = deepFreeze(JSON.parse(table[key]));
  PARSED.set(cacheKey, tree);
  return tree;
}

/**
 * Freeze value and everything inside it.
 *
 * @template T
 * @param {T} value
 * @returns {T}
 */
function deepFreeze(value) {
  if (value !== null && typeof value === "object") {
    for (const child of Object.values(value)) {
      deepFreeze(child);
    }
    Object.freeze(value);
  }
  return value;
}

/**
 * Return the entry for a map's technical name, or null when none is known.
 *
 * mapKey is the map or scenario technical name (for example
 * "tdm_map_id_47_teutoburg_forest_test" or "scenario_1_HRP_vs_MRP"). Any other
 * value, or a name with no entry, returns null. Pure lookup: no DOM, storage or
 * timers.
 *
 * @param {unknown} mapKey
 * @returns {Readonly<{kit: string, title: string | null, geometry: string, redZoneDepth: number, tale: boolean, floorSwitches?: number, stoneSwitches?: number, mapId?: number, scenarioId?: number}> | null}
 */
export function mapTaleSkin(mapKey) {
  return typeof mapKey === "string" && Object.hasOwn(MAP_SKIN_ENTRIES, mapKey)
    ? MAP_SKIN_ENTRIES[mapKey]
    : null;
}

/**
 * Return the stored tale floor tree for a technical name, or null.
 *
 * The first call for a name parses its JSON text and freezes the result; later
 * calls return the same frozen tree. Null when the name has no tale (unknown
 * name, or a layout that changed after its tale was drawn).
 *
 * @param {string} mapKey
 * @returns {ReadonlyArray<TaleNode> | null}
 */
export function taleFloorTree(mapKey) {
  return parsedTree(TALE_FLOOR_TEXT, "floor", mapKey);
}

/**
 * Return the stored tale stone tree for a technical name, or null.
 *
 * Same rules as taleFloorTree. The tree draws every stone of the catalogue
 * layout on its true footprint, with the tale's carvings and shadows.
 *
 * @param {string} mapKey
 * @returns {ReadonlyArray<TaleNode> | null}
 */
export function taleStoneTree(mapKey) {
  return parsedTree(TALE_STONE_TEXT, "stones", mapKey);
}
